from engine import *

PART4 = "Part 4. Maintenance and reliability"
ALL = ["Operator", "Engineer", "Reliability", "HSE", "Manager"]

def blocks():
    b = []
    # ------------------------------------------------------------------ 19 Maintenance overview
    b += [H1(19, "Maintenance overview", ALL, PART4,
             "The Maintenance page turns 211 work orders into charts, tables and simulations. Six views share one filter bar, so a choice made once applies to every view."),
          H2("The filter bar"),
          FIG("p4_dash", "The Maintenance page, Overview view.",
              [(1, "Equipment filter: **All equipment** or one set.", "^All equipment$"),
               (2, "The six views: Overview, Work orders, Timeline, Predictive, Plant replay and Site plan.", "^Overview$"),
               (3, "**Reliability report** opens a printable report for the selection.", "^Reliability report$"),
               (4, "**Generate records** adds sample work orders for testing. It is limited to Reliability and Manager.", "^Generate records$")], maxh=190),
          STEPS(["Select **All equipment** or one equipment tag.",
                 "In the **Period** strip, select one month or a whole year. Select a second month to set a range.",
                 "Read the six tiles under the strip: work orders, breakdowns, downtime, cost, MTBF and MTTR. They follow the selection.",
                 "Choose a view with the tabs."]),
          NOTE("tip", "The charts are also filters. Select a bar, a segment, a row or a cell and the work orders behind it open in a list."),
          H2("What the Overview shows"),
          TABLE(["Chart", "What it tells you", "Select to"],
                [["Work orders per month by type", "Workload split into preventive, corrective, predictive, inspection, calibration and overhaul", "List the work orders of a month"],
                 ["Breakdown downtime per month", "Hours lost in each month", "List that month's work orders"],
                 ["Cost split", "Cost by work type and by discipline, in IDR", "Filter by type or discipline"],
                 ["Equipment by month", "A heat map of work volume for each unit and month", "List the work orders of a cell"],
                 ["Reliability by equipment", "Breakdowns, MTBF, MTTR and availability for each unit", "Filter to one unit"],
                 ["Priority mix", "Emergency, high and medium work orders", "Filter by priority"],
                 ["Most frequent failure modes", "Instrument, seal, valve, bearing, vibration and blockage failures", "List the work orders of a mode"],
                 ["Planned versus unplanned", "Share of planned, condition-based and breakdown work", "List each group"]],
                [30, 46, 24]),
          NOTE("note", "A data note appears under the tiles when some work orders do not state whether they were breakdowns. Those work orders count as work orders but not as breakdowns, and the note gives the number."),
          ]
    # ------------------------------------------------------------------ 20 Work orders
    b += [H1(20, "Work orders", ALL, PART4,
             "The Work orders view lists every job in the selection, grouped by equipment. Each work order opens in a report that explains what happened, what caused it and what was done."),
          FIG("p4_table", "The Work orders view.",
              [(1, "Filters: work type, discipline, priority and breakdown.", "^All work types$"),
               (2, "**Export CSV** saves the filtered list.", "^Export CSV$"),
               (3, "A group for each unit, with its work orders, breakdowns, downtime and cost.", "^Feed/Charge Pump$")], maxh=170),
          STEPS(["Use the four filters to narrow the list. The count and the totals update.",
                 "Select the column heading **Reported** to change the sort order.",
                 "Select a row to open the work order report.",
                 "Select **Show all** at the foot of a group to see the rest of its work orders."]),
          H2("The work order report"),
          FIG("p4_wo", "A work order report.", maxh=170),
          P("The report has two panes. The left pane gives the problem, the cause, the action taken and the people and parts involved. The right pane shows the equipment drawing with the failed component highlighted and the location of the failure in the unit. Select **Incident pack** to produce a printable investigation pack, or **Print report** for a single page."),
          H2("The failure view"),
          P("When the work order was a breakdown, the report also offers a **Live** view. It replays the event on the P&ID or in 3D, with the failed part flagged and the units affected by the failure shown in turn."),
          FIG("p4_wo_fail", "A breakdown work order in the failure view.", maxh=170),
          ]
    # ------------------------------------------------------------------ 21 Timeline
    b += [H1(21, "Timeline", ALL, PART4,
             "The Timeline view shows when work happened. It is the quickest way to see whether jobs cluster, and whether a breakdown follows a particular kind of work."),
          FIG("p4_time", "The Timeline view.",
              [(1, "Each bar is a job. Its length is the duration. A diamond marks a breakdown.", "^Event timeline$"),
               (2, "**Plant overview**: a plot plan coloured by the number of breakdowns in the selected period.", "^Plant overview$"),
               (3, "A short assistant that answers questions about the selection.", "^Assistant$")], maxh=170),
          BUL(["Select a bar to open the work order report.",
               "Select a unit on the plant overview to see which of its components fail most and where it stands on the plot plan.",
               "Use the **Period** strip to zoom in on a month."]),
          ]
    # ------------------------------------------------------------------ 22 Predictive
    b += [H1(22, "Predictive maintenance", ["Engineer", "Reliability", "Manager"], PART4,
             "The Predictive view estimates which units are most likely to fail, when, and what that would cost. It is a prioritisation tool. It tells you where to look first; it does not predict a particular failure."),
          FIG("p4_pdm", "The Predictive view, Failure modes tab.",
              [(1, "Controls: **Export outlook**, chain reaction in priority, horizon and model.", "^Export outlook$"),
               (2, "Six tiles: units at high risk, expected failures, downtime, cost, nearest predicted failure and mean health.", "^Units at high risk$"),
               (3, "**Data confidence** states how reliable the numbers are.", "^Data confidence"),
               (4, "Risk matrix, health index by unit and failure probability.", "^Risk matrix$")], maxh=210),
          H2("Controls"),
          TABLE(["Control", "Use"],
                [["Horizon", "Choose 30, 90, 180 or 365 days. Expected failures, downtime and cost are scaled to the horizon."],
                 ["Model", "**Fleet breakdown rate** gives every unit the same rate and ranks by consequence. **Unit history (experimental)** uses each unit's own record."],
                 ["Include chain reaction in priority", "Adds the effect of a failure on connected units to the ranking."],
                 ["Action threshold", "The priority score above which a unit is flagged as high risk."]],
                [32, 68]),
          NOTE("caution", "Read the **Data confidence** line first. A unit with fewer than three breakdowns has a weak forecast, and component forecasts rest on one to three events. Treat them as a reason to go and look, not as a prediction. The default model uses the same rate for every unit because the backtest shows that a unit's own history does not predict its next breakdown."),
          H2("The six tabs"),
          TABLE(["Tab", "What it shows"],
                [["Failure modes", "Failure modes ranked by occurrence, severity and how easily they are detected"],
                 ["Reliability measures", "MTBF, MTTR and availability for the units in the selection"],
                 ["Next 90 days by mode", "The expected window of each failure over the coming period, with the health index and cumulative failure probability of the unit you select"],
                 ["Lessons in play", "The one point lessons that apply to the failure modes in view"],
                 ["Lesson use", "How often those lessons were opened and used"],
                 ["Combined score", "The priority score that combines the history, the consequence and the lessons"]],
                [28, 72]),
          FIG("p4_pdm_next", "The Next 90 days by mode tab.", maxh=210),
          ]
    # ------------------------------------------------------------------ 23 Reliability analysis
    b += [H1(23, "Reliability analysis", ["Engineer", "Reliability", "Manager"], PART4,
             "Reliability analysis connects what is failing to why. Use it to rank failure modes, find repeating causes and decide which preventive task earns its place."),
          FIG("p4_rel", "The failure modes and the reliability figures of a unit.", maxh=210),
          STEPS(["Open **Maintenance**, then the **Predictive** view.",
                 "Select the **Failure modes** tab, then the **Reliability measures** tab.",
                 "Select a unit in the health index list. The lower part of the page shows its health index, its risk level, the date it crosses the threshold and its cumulative failure probability.",
                 "Compare the **Mean time between failures** of units on the **Reliability by equipment** chart (Chapter 19) or the **Equipment compared** table (Chapter 27).",
                 "Open **Reliability report** to print the Pareto of root causes, the largest downtime events and the trends for the selection."]),
          NOTE("tip", "A repeated root cause across several units is a stronger signal than a single unit with many breakdowns. Check the **Most frequent failure modes** chart before you plan a task for one unit."),
          ]
    # ------------------------------------------------------------------ 24 Plant replay
    b += [H1(24, "Plant replay", ALL, PART4,
             "Plant replay plays back the maintenance history over the plant. As the date moves forward, units change state, work orders appear and breakdowns are flagged, so a sequence of events becomes easy to follow."),
          FIG("p4_replay", "Plant replay with the 3D plant.",
              [(1, "Playback buttons: **Play**, **Previous breakdown**, **Next breakdown** and **Restart**.", "^Play$"),
               (2, "**Speed**: Slow, Normal, Fast and Very fast.", "^Speed$"),
               (3, "**Pause on breakdown** stops the replay at each breakdown.", "Pause on breakdown"),
               (4, "**Failure view**: docked below or in a popup.", "^Failure view$"),
               (5, "The **Event track**. Red diamonds are breakdowns and dots are other work orders.", "^Event track$"),
               (6, "Switch between **Plot plan** and **3D plant**.", "^3D plant$")], maxh=210),
          STEPS(["Open **Maintenance** and select **Plant replay**.",
                 "Select **3D plant** to see the plant in three dimensions, or **Plot plan** for the flat map.",
                 "Tick **Pause on breakdown**, then select **Play**. The replay stops at the first breakdown.",
                 "Read the **Plant status** panel and the failure view. They show which unit is down and which work order is active.",
                 "Select **Play** again to continue, or select a point on the event track to jump to it."]),
          FIG("p4_replay2", "The 3D plant at a breakdown, with the failed unit flagged.", maxh=140),
          P("Units are coloured **Running**, **Notified** or **Breakdown**. The table under the plant lists, for each unit, its state, the active work order, its breakdowns, its downtime and its availability over the last 30 days."),
          ]
    # ------------------------------------------------------------------ 25 Site plan
    b += [H1(25, "Site plan", ["Engineer", "Reliability", "HSE", "Manager"], PART4,
             "The Site plan view plans the next 28 days of work. It turns routine intervals and forecast failures into jobs, fills crew days, adds the permits each job normally needs and checks the work next door."),
          NOTE("caution", "The planner is a planning aid built on the history. It is not a permit system."),
          FIG("p4_plan", "The Site plan view.",
              [(1, "Crew and crane limits, and the hot work separation distance.", "^Mechanical crews$"),
               (2, "Summary tiles: jobs, jobs from the forecast, crew hours, busiest day and permits.", "^Jobs in the plan$"),
               (3, "**Schedule by unit**. Letters mark the permits: H hot work, C confined space, L lift, I isolation, B line break.", "^Schedule by unit$"),
               (4, "**Site on the day** with crane pads, laydown areas and separation rings.", "^Site on the day$")], maxh=210),
          STEPS(["Select **Add example campaign** to load a sample campaign, or leave the plan as built from the history.",
                 "Set the number of crews and cranes, and the hot work separation in metres.",
                 "Read the **Clashes / warnings** tile. A clash means that two jobs conflict on crew, crane or separation.",
                 "Select a bar in the schedule to see why the job is there and which permits it needs. Move it to another day and the clash check runs again.",
                 "Select **Export CSV** to save the plan, or **Reset plan** to start again."]),
          ]
    # ------------------------------------------------------------------ 26 Failure memory
    b += [H1(26, "Failure Memory", ALL, PART4,
             "Failure Memory finds earlier cases that look like the one you have now. The search covers work orders, one point lesson troubleshooting cases and approved knowledge items."),
          FLOW("f_fm", [[("pill", "Describe the symptom"), ("box", "Compare with all work orders, OPL cases and approved items"), ("box", "Rank by text match, equipment and component")],
                        [("box", "Group and count the corrective actions"), ("dia", "Repeat within 90 days?", ""), ("pill", "Read the cases and open the source")]],
               "How Failure Memory finds similar failures."),
          FIG("p4_fm", "Failure Memory with the results for a seal leak.",
              [(1, "Equipment filter and the symptom box.", "^All equipment$"),
               (2, "**Find similar failures** runs the search.", "Find similar failures"),
               (3, "Example symptoms. Select one to fill the box.", "Mechanical seal leak on the hexane feed pump"),
               (4, "**Most frequent root causes** in the history. Select one to search for similar cases.", "^Most frequent root causes"),
               (5, "**Recommended actions**, the likely causes and the similar cases that support them.", "^Recommended action")], maxh=200),
          STEPS(["Select an equipment set, or leave **All equipment**.",
                 "Type the symptom in your own words, or select one of the example symptoms.",
                 "Select **Find similar failures**.",
                 "Read the **Recommended actions**. Each action shows how often it was used and whether the same failure was repeated within 90 days.",
                 "Read the **Probable root causes** and the **Similar past failures**. Select a case to open its work order or its lesson.",
                 "If your case is new, select **Report a failure** or **Capture tech knowledge** to record it (Chapter 34)."]),
          ]
    # ------------------------------------------------------------------ 27 Performance
    b += [H1(27, "Performance", ALL, PART4,
             "The Performance page shows the key indicators of the whole plant and of each equipment set, with targets, so that you can see at a glance what is on target and what is not."),
          FIG("p4_perf", "The Performance page, Reliability tab.",
              [(1, "Equipment filter: **Whole plant** or one set. **Export CSV** saves the figures.", "^Whole plant$"),
               (2, "Indicator tiles. A tag shows whether each is **On target** or **Off target**.", "^Availability"),
               (3, "Breakdowns and downtime by month, and work by type.", "^Breakdowns and downtime by month"),
               (4, "**Equipment compared**: all units side by side, with availability, MTBF, MTTR, cost, planned share, health and risk.", "^Equipment compared$")], maxh=210),
          H2("Reliability tab"),
          P("The tiles show availability, MTBF, MTTR, breakdowns, breakdown downtime, breakdowns per unit-year, the planned work share, maintenance cost, the average health index, the number of units at high forecast risk, the average cost per work order and the longest breakdown."),
          H2("Knowledge tab"),
          FIG("p4_perf_kn", "The Knowledge tab.", maxh=120),
          P("This tab measures the knowledge base: the share of documents with an approval status, the open data issues, the number of documents, the lessons and the user items. The table **Knowledge base status by equipment** shows, for each set, how many documents are approved and how many lessons and issues it has."),
          H2("Spare parts tab"),
          FIG("p4_perf_sp", "The Spare parts tab.", maxh=120),
          P("The Spare parts tab counts the parts used in the history, the parts expected to be needed within 90 days, the parts used in a breakdown and the parts used three times or more. A table lists each part with its use. Use it to decide which spares justify holding stock."),
          H2("Targets and data feeds tab"),
          FIG("p4_perf_tg", "The Targets and data feeds tab.", maxh=120),
          P("The **Targets** table shows each measure, its meaning and the target, such as the share of calendar time that a unit is ready to run. The **Data feeds** table lists the indicators that need live data, such as overall equipment effectiveness, energy use and throughput, with the system they come from and the reason they matter. These indicators are shown as not available until the feed is connected."),
          ]
    return b
